import { z } from 'zod';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import { guidanceSourceDigest } from '../../storage/profiles/guidanceVerifier';
import {
  GuidanceError,
  guidanceWarning,
  type GuidanceUpload,
  type GuidanceAttachment,
} from '../../types/guidance';
import {
  GuidanceSourceSchema,
  GuidanceSourceCreateSchema,
  type GuidanceSource,
} from '../../types/guidance-source';
import type { TelemetryService } from '../TelemetryService';
import { readGuidanceSource } from '../guidanceSource';
import { remoteSourceInterval } from './SourceSyncSchedule';
import type { SavedGuidance } from '../../types/guidance';
import {
  LOCAL_SOURCE_POLL_MS,
  type SourceSyncCheck,
  type SourceSyncMode,
  type SourceSyncTrigger,
  assertExplicitSourceSync,
  isSourceSyncAllowed,
} from '../../types/source-sync';

interface GuidanceSyncOptions {
  accountId: () => string | undefined;
  withRecords: <T>(
    operation: (records: ProfileRecords) => Promise<T> | T,
    accountId?: string,
  ) => Promise<T>;
  serialize: <T>(
    operation: (records: ProfileRecords) => Promise<T> | T,
    accountId: string,
  ) => Promise<T>;
  importImages: (
    records: ProfileRecords,
    input: Pick<GuidanceUpload, 'markdown' | 'images'>,
  ) => Promise<GuidanceAttachment[]>;
  telemetry?: Pick<TelemetryService, 'trackGuidanceOperation'>;
  signal: AbortSignal;
}

const sourceInterval = (document: SavedGuidance): number =>
  document.origin?.source.kind === 'file'
    ? LOCAL_SOURCE_POLL_MS
    : remoteSourceInterval(document.id);

export const guidanceSyncChecks = (
  documents: readonly SavedGuidance[],
): SourceSyncCheck[] =>
  documents.flatMap((document) =>
    document.origin &&
    document.sync &&
    document.syncMode &&
    isSourceSyncAllowed({ syncMode: document.syncMode, trigger: 'automatic' })
      ? [
          {
            family: 'context' as const,
            sourceId: document.id,
            dueAt:
              Date.parse(document.sync.checkedAt) + sourceInterval(document),
          },
        ]
      : [],
  );

export class GuidanceSync {
  constructor(private readonly options: GuidanceSyncOptions) {}

  private assertAccount(
    accountId: string | undefined,
    signal?: AbortSignal,
  ): void {
    if (!accountId || accountId !== this.options.accountId())
      throw new GuidanceError(
        'guidance_account_changed',
        'Saved guidance account changed. Sign in and retry.',
      );
    signal?.throwIfAborted();
  }

  private async readSource(
    source: GuidanceSource,
    options: { previousRevision?: string; signal?: AbortSignal } = {},
  ) {
    try {
      return await readGuidanceSource(source, options);
    } catch (error) {
      options.signal?.throwIfAborted();
      if (error instanceof GuidanceError || error instanceof z.ZodError)
        throw error;
      throw new GuidanceError(
        'guidance_source_unavailable',
        'The document source could not be read. Check its location, branch and access permissions.',
      );
    }
  }

  async add(
    input: z.input<typeof GuidanceSourceCreateSchema>,
    expectedAccountId?: string,
  ) {
    const { source, ...metadata } = GuidanceSourceCreateSchema.parse(input);
    const accountId = this.options.accountId();
    return this.options.withRecords(async (records) => {
      const content = await this.readSource(source, {
        signal: this.options.signal,
      });
      if (!content) throw new Error('Source content is unavailable');
      this.assertAccount(accountId, this.options.signal);
      const attachments = await this.options.importImages(records, content);
      this.assertAccount(accountId);
      const now = new Date().toISOString();
      const document = records.addGuidance({
        ...metadata,
        markdown: content.markdown,
        attachments,
        origin: { source, revision: content.revision },
        sync: { checkedAt: now, syncedAt: now },
      });
      return this.withWarning(records, document);
    }, expectedAccountId);
  }

  async connect(
    input: { id: string; source: GuidanceSource },
    expectedAccountId?: string,
  ) {
    const source = GuidanceSourceSchema.parse(input.source);
    const accountId = this.options.accountId();
    return this.options.withRecords(async (records) => {
      const before = records.getGuidance(input.id);
      const content = await this.readSource(source, {
        signal: this.options.signal,
      });
      if (!content) throw new Error('Source content is unavailable');
      this.assertAccount(accountId, this.options.signal);
      const attachments = await this.options.importImages(records, content);
      this.assertAccount(accountId);
      if (
        guidanceSourceDigest(before) !==
          guidanceSourceDigest(records.getGuidance(input.id)) ||
        JSON.stringify(before.origin) !==
          JSON.stringify(records.getGuidance(input.id).origin)
      )
        throw new GuidanceError(
          'guidance_source_changed',
          'Saved guidance changed while the source was read. Retry the connection.',
        );
      const now = new Date().toISOString();
      const document = records.updateGuidance({
        id: input.id,
        markdown: content.markdown,
        attachments,
        origin: { source, revision: content.revision },
        sync: { checkedAt: now, syncedAt: now },
      });
      return this.withWarning(records, document);
    }, expectedAccountId);
  }

  async disconnect(id: string, expectedAccountId?: string) {
    return this.options.withRecords(
      (records) => records.updateGuidance({ id, origin: null, sync: null }),
      expectedAccountId,
    );
  }

  async setSyncMode(
    input: { id: string; syncMode: SourceSyncMode },
    expectedAccountId?: string,
  ) {
    return this.options.withRecords(
      (records) => records.setGuidanceSyncMode(input),
      expectedAccountId,
    );
  }

  private withWarning(
    records: ProfileRecords,
    document: ReturnType<ProfileRecords['getGuidance']>,
  ) {
    const warning = guidanceWarning(
      records.resolveGuidance({ mode: 'auto', excludedIds: [] }),
    );
    return { ...document, ...(warning ? { guidanceWarning: warning } : {}) };
  }

  async refresh({
    accountId,
    ids,
    trigger,
    signal,
  }: {
    accountId: string;
    ids: readonly string[];
    trigger: SourceSyncTrigger;
    signal: AbortSignal;
  }): Promise<void> {
    this.assertAccount(accountId, signal);
    await this.options.serialize(async (records) => {
      const documents = records.listGuidance();
      if (trigger === 'explicit')
        for (const document of documents)
          if (ids.includes(document.id) && document.syncMode)
            assertExplicitSourceSync(document.syncMode);
      for (const saved of documents) {
        if (!ids.includes(saved.id) || !saved.origin || !saved.sync) continue;
        if (
          trigger === 'automatic' &&
          (!saved.syncMode ||
            !isSourceSyncAllowed({ syncMode: saved.syncMode, trigger }))
        )
          continue;
        const origin = saved.origin;
        const sync = saved.sync;
        const isCurrent = (): boolean => {
          this.assertAccount(accountId, signal);
          try {
            return (
              JSON.stringify(records.getGuidance(saved.id).origin) ===
              JSON.stringify(origin)
            );
          } catch (error) {
            if (
              error instanceof GuidanceError &&
              error.code === 'guidance_not_found'
            )
              return false;
            throw error;
          }
        };
        const started = Date.now();
        try {
          const content = await this.readSource(origin.source, {
            previousRevision: origin.revision,
            signal,
          });
          if (!isCurrent()) continue;
          const checkedAt = new Date().toISOString();
          if (!content || content.revision === origin.revision) {
            records.updateGuidance({
              id: saved.id,
              sync: { checkedAt, syncedAt: sync.syncedAt },
            });
            continue;
          }
          const attachments = await this.options.importImages(records, content);
          if (!isCurrent()) continue;
          records.updateGuidance({
            id: saved.id,
            markdown: content.markdown,
            attachments,
            origin: { source: origin.source, revision: content.revision },
            sync: { checkedAt, syncedAt: checkedAt },
          });
          this.options.telemetry?.trackGuidanceOperation({
            operation: 'sync',
            outcome: 'completed',
            durationMs: Date.now() - started,
            documentCount: 1,
          });
        } catch (error) {
          if (!isCurrent()) continue;
          const errorCode =
            error instanceof z.ZodError ||
            (error instanceof GuidanceError &&
              error.code === 'guidance_asset_invalid')
              ? 'document_invalid'
              : 'source_unavailable';
          records.updateGuidance({
            id: saved.id,
            sync: {
              checkedAt: new Date().toISOString(),
              syncedAt: sync.syncedAt,
              error: errorCode,
            },
          });
          if (saved.sync?.error !== errorCode)
            this.options.telemetry?.trackGuidanceOperation({
              operation: 'sync',
              outcome: 'failed',
              durationMs: Date.now() - started,
              documentCount: 1,
              errorCode: 'guidance_unavailable',
            });
        }
      }
    }, accountId);
  }
}
